#include "../src/rounded_panel.hpp"
#include <cassert>
#include <iostream>
int main(){auto p=day::roundedPanelMask();assert(p.size()==32*32*4);bool fractional=false;for(int y=0;y<32;++y)for(int x=0;x<32;++x){auto a=p[(y*32+x)*4+3];assert(a==p[(y*32+31-x)*4+3]&&a==p[((31-y)*32+x)*4+3]);assert(p[(y*32+x)*4]==255);fractional|=a>0&&a<255;if(x>=8&&x<24||y>=8&&y<24)assert(a==255);}assert(fractional&&p[3]==0&&p[(8*32+8)*4+3]==255);for(float r:{2.f,2.5f,3.f,16.f,24.f,88.f,136.f,138.f}){auto pixels=day::circleMask(r);int n=int(std::ceil(r*2))+2,partial=0;assert(pixels.size()==size_t(n*n*4));for(int y=0;y<n;y++)for(int x=0;x<n;x++){int a=pixels[(y*n+x)*4+3];partial+=a>0&&a<255;assert(a==pixels[(y*n+(n-1-x))*4+3]);assert(a==pixels[((n-1-y)*n+x)*4+3]);}assert(partial>0&&pixels[3]==0&&pixels[((n/2)*n+n/2)*4+3]==255);}std::cout<<"Rounded panel: fractional edge coverage, opaque interior, clear corners and symmetric masks plus supersampled circles passed\n";}
